#!/usr/bin/env node
/**
 * Derive Open Graph / Twitter card metadata for every routed Site B page.
 *
 * WHY THIS IS DERIVED AND NOT HAND-AUTHORED. og:title, og:description and
 * og:url are restatements of three fields the pages already carry: <title>,
 * <meta name="description"> and <link rel="canonical">. Hand-authoring them
 * would be a second source of truth for each, and this repo already knows how
 * that ends — the cover tile said "20 terms" against a 28-term file.
 *
 * It matters more here than anywhere else in the site, because three of the
 * eleven pages are GENERATED by cloning part-6's shell. The generators rewrite
 * title, canonical and description with their own targeted replaces; they know
 * nothing about og tags. Hand-authoring an og:title into part-6 would stamp
 * Part 6's identity onto glossary, framework-in-math and framework-in-pictures
 * — silently, and only visible when someone shared the link. Deriving after
 * the generators run means the clone can't carry the donor's identity.
 *
 * Ordering therefore matters: this MUST run after build:glossary /
 * build:pictures / build:math in prebuild, and it re-reads from disk.
 *
 * The block it writes is delimited and rewritten wholesale on every run, so
 * running twice is a no-op and an edited block is corrected rather than
 * duplicated.
 *
 * Run:   npm run build:social-meta
 * Check: npm run audit:social      (no browser, safe in any pipeline)
 */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const SITE = path.join(ROOT, 'public', 'site-b');
const MANIFEST = path.join(SITE, 'brand', 'social', 'cards.json');
const CHECK = process.argv.includes('--check');

/** Every page reachable on a clean slug (see next.config.mjs siteBRewrites). */
const PAGES = [
  'cover-docs', 'part-1-foundation', 'part-1-pictures', 'part-2-lineage-macro',
  'part-3-bitcoin-convexity', 'part-4-tax-architecture', 'part-5-portfolio-construction',
  'part-6-convexity-scoring', 'glossary', 'framework-in-math', 'framework-in-pictures',
];

const BEGIN = '  <!-- BEGIN generated social meta — build-social-meta.mjs. Do not edit by hand. -->';
const END = '  <!-- END generated social meta -->';
const BLOCK = new RegExp(`\\n${escapeRe(BEGIN)}[\\s\\S]*?${escapeRe(END)}`, 'g');

function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

/** Attribute-safe. Input is already HTML-escaped in the source head, so this
 *  only has to survive re-embedding, not re-escape from scratch. */
const attr = (s) => s.replace(/"/g, '&quot;');

function field(html, re, what, page) {
  const m = html.match(re);
  if (!m) throw new Error(`${page}: no ${what} in <head> — social meta cannot be derived from it`);
  return m[1].trim();
}

function readPage(page) {
  const file = path.join(SITE, `${page}.html`);
  const html = fs.readFileSync(file, 'utf8');
  return {
    page,
    file,
    html,
    title: field(html, /<title>([\s\S]*?)<\/title>/, '<title>', page),
    description: field(html, /<meta name="description" content="([^"]*)"/, 'meta description', page),
    url: field(html, /<link rel="canonical" href="([^"]*)"/, 'canonical link', page),
  };
}

/** Cards are optional: a page without one falls back to the site card, so a
 *  new page previews correctly the moment it exists rather than after someone
 *  remembers to render art for it. */
function cardFor(page) {
  const rel = `/site-b/brand/social/${page}.png`;
  return fs.existsSync(path.join(SITE, 'brand', 'social', `${page}.png`))
    ? rel
    : '/site-b/brand/social/default.png';
}

function render({ title, description, url, page }) {
  const image = cardFor(page);
  return `
${BEGIN}
  <meta property="og:type" content="${page === 'cover-docs' ? 'website' : 'article'}">
  <meta property="og:site_name" content="The Adaptive Convexity Framework">
  <meta property="og:title" content="${attr(title)}">
  <meta property="og:description" content="${attr(description)}">
  <meta property="og:url" content="${attr(url)}">
  <meta property="og:image" content="https://docs.acfdashboard.com${image}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:image:alt" content="${attr(title)}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="${attr(title)}">
  <meta name="twitter:description" content="${attr(description)}">
  <meta name="twitter:image" content="https://docs.acfdashboard.com${image}">
${END}`;
}

const problems = [];
let written = 0;

for (const page of PAGES) {
  const meta = readPage(page);
  const block = render(meta);
  const stripped = meta.html.replace(BLOCK, '');

  // Anchor after the canonical link: the og:url derives from it, so keeping
  // them adjacent makes a mismatch visible in review rather than 40 lines apart.
  const anchor = stripped.match(/  <link rel="canonical" href="[^"]*">/);
  if (!anchor) { problems.push(`${page}: no canonical anchor to insert after`); continue; }
  const at = anchor.index + anchor[0].length;
  const next = stripped.slice(0, at) + block + stripped.slice(at);

  if (CHECK) {
    if (next !== meta.html) problems.push(`${page}: social meta is stale — run \`npm run build:social-meta\``);
  } else if (next !== meta.html) {
    fs.writeFileSync(meta.file, next);
    written += 1;
  }
}

// Card drift: a card bakes the page title into pixels, so a title edit silently
// invalidates the art. The manifest records what each card was rendered from;
// comparing it to the live title catches that without needing to read a PNG.
if (fs.existsSync(MANIFEST)) {
  const manifest = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  for (const [page, recorded] of Object.entries(manifest.cards || {})) {
    if (!PAGES.includes(page)) { problems.push(`card manifest lists unknown page "${page}"`); continue; }
    const live = readPage(page).title;
    if (live !== recorded.title) {
      problems.push(`${page}: card art was rendered from a different title — re-run \`npm run build:social-cards\`\n      card: ${recorded.title}\n      page: ${live}`);
    }
  }
} else if (CHECK) {
  problems.push('no card manifest at public/site-b/brand/social/cards.json — run `npm run build:social-cards`');
}

if (problems.length) {
  console.error(`Social meta ${CHECK ? 'audit' : 'build'} failed:\n  - ${problems.join('\n  - ')}`);
  process.exit(1);
}

console.log(CHECK
  ? `Social audit passed: ${PAGES.length} pages carry derived og/twitter metadata, every card matches its page title.`
  : `Social meta built: ${PAGES.length} pages checked, ${written} updated.`);
